
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_mpw1pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_mpw1pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.307592044753453e+00, -3.245255682592308e+00, -3.157940146518332e+00, -3.037055838530259e+00, -2.872483609464080e+00, -2.653767781537388e+00, -2.372938745482258e+00, -2.029595886450553e+00, -1.637692308292847e+00, -1.228525602392161e+00, -8.337511810994175e-01, -5.720065770007956e-01, -4.991866113843011e-01, -4.099503750260565e-01, -2.952317618384967e-01, -1.883246912499918e-01, -1.087968608654584e-01, -3.694617312113679e-02, -9.454875783539706e-04, -2.361594564499045e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


